:root {
  /* Colors */
  --color-fog-canvas: #eeefe9;
  --color-paper-card: #fdfdf8;
  --color-quartz-white: #ffffff;
  --color-stone-strip: #e5e7e0;
  --color-ink: #111111;
  --color-graphite-nav: #23251d;
  --color-pewter-caption: #65675e;
  --color-ash-hint: #9ea096;
  --color-pebble-border: #bfc1b7;
  --color-sunbeam-amber: #eb9d2a;
  --color-ochre-key: #cd8407;
  --color-bronze-edge: #b17816;
  --color-ember-signal: #f54e00;

  /* Typography — Font Families */
  --font-roundhog: "RoundHog", "Figtree", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-source-code-pro: "Source Code Pro", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.78;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.25;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.43;
  --tracking-body: 0px;
  --text-body-lg: 17px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 18px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 18px;
  --leading-heading-sm: 1.56;
  --tracking-heading-sm: 0px;
  --text-heading: 24px;
  --leading-heading: 1.33;
  --tracking-heading: -0.6px;
  --text-heading-lg: 30px;
  --leading-heading-lg: 1.33;
  --tracking-heading-lg: -0.75px;
  --text-display: 36px;
  --leading-display: 1.11;
  --tracking-display: -0.9px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-bold-2: 800;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-44: 44px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-content-width: 1024px;
  --layout-text-measure: 672px;
  --layout-section-gap: 64px;
  --layout-card-padding: 16px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-cards: 4px;
  --radius-tags: 4px;
  --radius-badges: 4px;
  --radius-nav: 4px;
  --radius-buttons: 6px;
  --radius-sections: 6px;
  --radius-buttons-hero: 8px;
  --radius-images: 20px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(0, 0, 0, 0.05);
  --shadow-sm: 0px 2.5px 0px 0px rgba(210, 211, 204, 1);
  --shadow-sm-2: inset 0px 0px 0px 0.5px rgba(0, 0, 0, 0.25), 0px 1px 2px 0px rgba(0, 0, 0, 0.25);
  --shadow-md: 0px 4px 6px -1px rgba(0, 0, 0, 0.1), 0px 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0px 20px 25px -5px rgba(0, 0, 0, 0.1), 0px 8px 10px -6px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0px 25px 50px -12px rgba(0, 0, 0, 0.25);

  /* Surfaces */
  --surface-fog-canvas: #eeefe9;
  --surface-stone-strip: #e5e7e0;
  --surface-paper-card: #fdfdf8;
  --surface-quartz-white: #ffffff;
  --surface-ember-signal: #f54e00;
}

